------------ import ------------
local KTool = CS.Engine.Lib.KTool
------------ import ------------
local CommonPlayerHeadNode = "Game.Behaviours.CommonPlayerHeadNode"
local comp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
local CommonGoodsList = "Game.Behaviours.CommonGoodsList"
local FishingUtils = import('Game.UI.Fishing.FishingUtils')

---@class UIFishpoolActivityRankNode
---@field Env                           	UIFishpoolActivityRankNode                                     
---@field controller                    	Engine.Modules.LuaBehaviour | Engine.UI.UILuaDialog
---@field TextNoReward                  	UnityEngine.RectTransform               
---@field ImgMyself                     	UnityEngine.RectTransform               
---@field CommonGoodsList               	UnityEngine.RectTransform               
---@field TextLevel                     	UnityEngine.RectTransform               
---@field ImgRank                       	UnityEngine.RectTransform               
---@field CommonPlayerHeadNode          	UnityEngine.RectTransform               
---@field BtnDetails                    	UnityEngine.RectTransform               
---@field TxtDamage                     	UnityEngine.RectTransform               
---@field TxtName                       	UnityEngine.RectTransform               
---@field Imgbg                         	UnityEngine.RectTransform               
---@field Txtranking                    	UnityEngine.RectTransform                         
local UIFishpoolActivityRankNode = Class('UIFishpoolActivityRankNode')

function UIFishpoolActivityRankNode:__init()
    self._data = nil
    self._commonPlayerHeadNodeScr = nil
end

function UIFishpoolActivityRankNode:__delete()
    self._data = nil
    self._commonPlayerHeadNodeScr = nil
end

function UIFishpoolActivityRankNode:Awake()
    if not self._commonPlayerHeadNodeScr then
        self._commonPlayerHeadNodeScr = CfUtils.GetLuaScr(self.CommonPlayerHeadNode, CommonPlayerHeadNode)
    end
    SetButtonAction(self.BtnDetails, Bind(self, self.OnBtnTeamInfo))
end

---Refresh
---@param data table 
function UIFishpoolActivityRankNode:Refresh(data, isMe, activityId)
    if not data then
        return
    end
    self._data = data
    self._activityId = activityId

    if isMe then 
        self:FillMeInfo()
    else
        self:FillOtherInfo()
    end
end

--通用的
function UIFishpoolActivityRankNode:FillCommonInfo()
    CfUtils.FillText(self.TxtDamage, checkNumber(self._data.score))
    CfUtils.FillText(self.Txtranking, checkNumber(self._data.rank))
    CfUtils.FillText(self.TextLevel, "Lv."..checkNumber(self._data.level))


    local status = checkNumber(self._data.rank) > 4 and 5 or checkNumber(self._data.rank)
    CfUtils.SetUISwitchText(self.Txtranking, status)
    CfUtils.SetUISwitchImage(self.ImgRank, status)
    CfUtils.SetUISwitchImage(self.controller.gameObject.transform:Find("ImgRank2"), status)
    CfUtils.FillImage(self.ImageBg, CfUtils.GetRankListBg(checkNumber(self._data.rank)), false)

    local playerInfo = self._data
    if playerInfo then
        if self._commonPlayerHeadNodeScr then
            self._commonPlayerHeadNodeScr:FreshAvatarFrame(playerInfo.avatar, playerInfo.avatarFrame)
        end
        --if self._scale then
        --    CfUtils.SetScale(self.CommonPlayerHeadNode, self._scale)
        --else
        --    CfUtils.SetScale(self.CommonPlayerHeadNode, (checkNumber(self._data.rank) > 3) and Vector3(0.3, 0.3, 1) or Vector3(0.4, 0.4, 1))
        --end

        CfUtils.FillText(self.TxtName, playerInfo.name)
        local playerDojo = comp:GetPlayerDojo()
        KTool.SetActive(self.ImgMyself, (checkNumber(playerInfo.playerId) == checkNumber(playerDojo.playerId)))
    end
end


--绘制别人的
function UIFishpoolActivityRankNode:FillOtherInfo()
    self:FillCommonInfo()
    self:FillRankReward()
end

--绘制自己的
function UIFishpoolActivityRankNode:FillMeInfo()
    self:FillCommonInfo()
    self:FillRankReward(true, checkNumber(self._data.presentageRank))

    
    local status = checkNumber(self._data.rank) > 4 and 5 or checkNumber(self._data.rank)
    CfUtils.SetUISwitchText(self.Txtranking, status)
    CfUtils.SetUISwitchImage(self.ItileRank.transform:Find("ImgRank"), status)

    self:FillPercentageRank(checkNumber(self._data.presentageRank))

    if checkNumber(self._data.rank) == 0 and checkNumber(self._data.presentageRank) == 0 then
        CfUtils.FillText(self.Txtranking, localize("未上榜"))
        CfUtils.SetUISwitchImage(self.ItileRank.transform:Find("ImgRank"), 5)
    end
end

--奖励
function UIFishpoolActivityRankNode:FillRankReward(isMe, percentageRank)
    local scr = CfUtils.GetLuaScr(self.CommonGoodsList, CommonGoodsList)
    if scr then
        local t = {}
        if isMe then
            percentageRank = checkNumber(percentageRank)
            --在排行榜上
            if percentageRank <= 0 then
                t = FishingUtils.GetRankRewardByRankNum(checkNumber(self._data.rank), self._activityId)
            else
                local vo = self:GetRankVo(percentageRank)

                local rewardT = checkTable(CfUtils.Split(vo.reward))
                local rewardNumT = checkTable(CfUtils.Split(vo.rewardNum))
                for k, v in pairs(rewardT) do
                    table.insert(t, {
                        goodsId = rewardT[k],
                        num = rewardNumT[k],
                    })
                end
            end
        else
            t = FishingUtils.GetRankRewardByRankNum(checkNumber(self._data.rank), self._activityId)
        end
        local isHaveReard = true

        if not t or table.count(t) <= 0 then
            isHaveReard = false
        end
        KTool.SetActive(self.CommonGoodsList, isHaveReard)
        KTool.SetActive(self.TextNoReward, not isHaveReard)

        if isHaveReard then
            scr:FreshBaseUI(t, false)
        end
    end
end

function UIFishpoolActivityRankNode:FillPercentageRank(num)
    num = checkNumber(num)

    CfUtils.SetActive(self.ItileRank.transform:Find("Layout/Txtranking2"), num > 0)

    if num > 0 then
        local vo = self:GetRankVo(num)
        if vo then
            CfUtils.FillText(self.ItileRank.transform:Find("Layout/Txtranking2"), vo.name)
        end
    end
    CfUtils.SetActive(self.BtnDetails, num <= 0)

    CfUtils.SetActive(self.Txtranking, num <= 0)
    CfUtils.SetActive(self.ItileRank.transform:Find("ImgRank"), num <= 0)
end

function UIFishpoolActivityRankNode:GetRankVo(num)
    local t = CfUtils.GetCf(AutoIds.IdSetting2711, "FishRankingRewardVo", true)
    if not t then
        return {}
    end
    for k, v in pairs(t) do
        if checkNumber(v.type) == 2 and checkNumber(self._activityId) == checkNumber(v.activityId) then
            if num >= checkNumber(v.upperLimit) and num <= checkNumber(v.lowerLimit) then
                return v
            end
        end
    end
    return {}
end

function UIFishpoolActivityRankNode:OnBtnTeamInfo()
    if not self._data then
        return
    end
    self._data = checkTable(self._data)

    local t = checkTable(self._data.records)
    table.sort(t, function(a, b)
        return checkNumber(a.score) > checkNumber(b.score)
    end)

    GameUtils.ShowCommonFishTipsBoard(self.BtnDetails, t, self._data.name)
end

function UIFishpoolActivityRankNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIFishpoolActivityRankNode
